import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import LoginPage from './index';

// We need to mock the AuthProvider context for the LoginPage
// The real AuthProvider makes network calls on mount, so we provide a mock context
const mockAuthContext = {
  isAuthenticated: false,
  hasCheckedAuth: true,
  localLogin: fn(),
  logoutAndRedirect: fn(),
  dispatchAuthenticated: fn(),
};

const meta = {
  component: LoginPage,
  tags: ['ai-generated'],
  args: {
    ignoreAuthCheck: true,
  },
} satisfies Meta<typeof LoginPage>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas }) => {
    await expect(canvas.getByTestId('login-username')).toBeVisible();
    await expect(canvas.getByTestId('login-password')).toBeVisible();
    await expect(canvas.getByTestId('login-submit')).toBeVisible();
  },
};

export const FilledForm: Story = {
  play: async ({ canvas, userEvent }) => {
    const usernameInput = canvas.getByTestId('login-username');
    const passwordInput = canvas.getByTestId('login-password');

    await userEvent.type(usernameInput, 'admin');
    await userEvent.type(passwordInput, 'password123');

    await expect(usernameInput).toHaveValue('admin');
    await expect(passwordInput).toHaveValue('password123');
  },
};

export const CssCheck: Story = {
  play: async ({ canvas }) => {
    const submitButton = canvas.getByTestId('login-submit');
    // The Login button uses LeafyGreen's baseGreen variant
    await expect(getComputedStyle(submitButton).display).not.toBe('');
  },
};

