import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import { Button } from '@leafygreen-ui/button';
import Popconfirm from './index';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    children: 'Are you sure you want to delete this item?',
    onConfirm: fn(),
  },
  render: (args) => (
    <div style={{ padding: '100px' }}>
      <Popconfirm {...args}>
        <Button>Delete</Button>
      </Popconfirm>
    </div>
  ),
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Delete')).toBeVisible();
  },
};

export const Opened: Story = {
  args: {
    children: 'Confirm this action?',
    open: true,
    setOpen: fn(),
    onConfirm: fn(),
  },
  render: (args) => (
    <div style={{ padding: '100px' }}>
      <Popconfirm {...args}>
        <Button>Action</Button>
      </Popconfirm>
    </div>
  ),
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    await expect(doc.querySelector('[role="tooltip"]')).toBeInTheDocument();
  },
};

export const CustomConfirmText: Story = {
  args: {
    children: 'Deploy to production?',
    confirmText: 'Deploy',
    open: true,
    setOpen: fn(),
    onConfirm: fn(),
  },
  render: (args) => (
    <div style={{ padding: '100px' }}>
      <Popconfirm {...args}>
        <Button>Trigger</Button>
      </Popconfirm>
    </div>
  ),
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    const tooltip = doc.querySelector('[role="tooltip"]');
    await expect(tooltip).toBeInTheDocument();
    await expect(tooltip?.textContent).toContain('Deploy');
  },
};

