import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn } from 'storybook/test';
import { TreeSelect, TreeDataEntry } from './TreeSelect';

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

const sampleData: TreeDataEntry[] = [
  { title: 'All', value: 'all', key: 'all' },
  {
    title: 'Frontend',
    value: 'frontend',
    key: 'frontend',
    children: [
      { title: 'React', value: 'react', key: 'react' },
      { title: 'Vue', value: 'vue', key: 'vue' },
    ],
  },
  {
    title: 'Backend',
    value: 'backend',
    key: 'backend',
    children: [
      { title: 'Node', value: 'node', key: 'node' },
      { title: 'Go', value: 'go', key: 'go' },
    ],
  },
];

export const NoneSelected: Story = {
  args: {
    state: [],
    tData: sampleData,
    onChange: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Frontend')).toBeVisible();
    await expect(canvas.getByText('Backend')).toBeVisible();
  },
};

export const SomeSelected: Story = {
  args: {
    state: ['react', 'node'],
    tData: sampleData,
    onChange: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('React')).toBeVisible();
    await expect(canvas.getByText('Node')).toBeVisible();
  },
};

export const AllSelected: Story = {
  args: {
    state: ['all', 'frontend', 'react', 'vue', 'backend', 'node', 'go'],
    tData: sampleData,
    onChange: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
  },
};

export const WithFilterControls: Story = {
  args: {
    state: ['react'],
    tData: sampleData,
    onChange: fn(),
    onFilter: fn(),
    onReset: fn(),
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Filter')).toBeVisible();
  },
};

export const Interactive: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return (
      <TreeSelect
        state={state}
        tData={sampleData}
        onChange={setState}
      />
    );
  },
  play: async ({ canvas, userEvent }) => {
    // LeafyGreen checkbox has pointer-events:none on input, click the label instead
    const reactLabel = canvas.getByText('React');
    await userEvent.click(reactLabel);
    // After clicking, the React checkbox input should be checked
    await expect(canvas.getByLabelText('React')).toBeChecked();
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { http, HttpResponse } from 'msw';
import LoginPage from './index';
import { AuthProvider } from '../../context/AuthProvider';

const meta = {
  component: LoginPage,
  tags: ['ai-generated'],
  args: {
    ignoreAuthCheck: true,
  },
  parameters: {
    msw: {
      handlers: [
        // Return auth failure so LoginPage renders the form instead of redirecting
        http.post('http://localhost:9090/graphql/query', () =>
          new HttpResponse(null, { status: 401 }),
        ),
      ],
    },
  },
  decorators: [
    (Story) => (
      <AuthProvider
        evergreenAppURL="http://localhost:9090"
        remoteAuthURL="http://localhost:9090/login"
        localAuthRoute="/login"
        shouldUseLocalAuth={true}
      >
        <Story />
      </AuthProvider>
    ),
  ],
} satisfies Meta<typeof LoginPage>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvas }) => {
    await waitFor(() => {
      expect(canvas.getByLabelText('Username')).toBeVisible();
    });
    await expect(canvas.getByLabelText('Password')).toBeVisible();
    await expect(canvas.getByRole('button', { name: /login/i })).toBeVisible();
  },
};

export const FilledForm: Story = {
  play: async ({ canvas, userEvent }) => {
    await waitFor(() => {
      expect(canvas.getByLabelText('Username')).toBeVisible();
    });
    const usernameInput = canvas.getByLabelText('Username');
    const passwordInput = canvas.getByLabelText('Password');

    await userEvent.type(usernameInput, 'admin', { delay: 50 });
    await userEvent.type(passwordInput, 'secret', { delay: 50 });

    await waitFor(() => {
      expect(usernameInput).toHaveValue('admin');
    });
    await waitFor(() => {
      expect(passwordInput).toHaveValue('secret');
    });
  },
};

export const CssCheck: Story = {
  play: async ({ canvas }) => {
    await waitFor(() => {
      expect(canvas.getByRole('button', { name: /login/i })).toBeVisible();
    });
    const loginButton = canvas.getByRole('button', { name: /login/i });
    // LeafyGreen Button renders with display flex
    await expect(getComputedStyle(loginButton).display).toBe('flex');
  },
};

